#[ignore = "private subprocess entry used only by RunningFixture"]
fn owned_lifecycle_process_fixture() {
    if std::env::var(FIXTURE_ENV).as_deref() != Ok("1") {
        return;
    }
    std::io::stderr().write_all(FIXTURE_READY).unwrap();
    let mut byte = [0_u8; 1];
